import{S as t,o as n,c as e,a9 as p,B as h}from"./chunks/framework.IJ8axLs_.js";const l="/agentsrc/images/claudecode/04-compact-pipeline.svg",k="/agentsrc/images/claudecode/04-compact-thresholds.svg",o="/agentsrc/images/claudecode/04-cache-paths.svg",r="/agentsrc/images/claudecode/04-sm-offload.svg",y=JSON.parse('{"title":"Claude Code 压缩源码拆解：五级流水线，把调 LLM 留到最后","description":"","frontmatter":{"title":"Claude Code 压缩源码拆解：五级流水线，把调 LLM 留到最后"},"headers":[],"relativePath":"claudecode/04-compact.md","filePath":"claudecode/04-compact.md","lastUpdated":1790217011000}'),d={name:"claudecode/04-compact.md"},F=Object.assign(d,{setup(c){const i=[{question:"Claude Code 五级压缩机制的核心设计思想是什么？",options:["在所有对话历史环节追求最大化的 token 节省效果","保证每次 API 调用前都执行一次全量上下文压缩操作","优先用数据结构变换解决问题仅在必要时调用 LLM 做摘要","始终调用 LLM 以获取最高质量的语义摘要结果"],correct:2,explanation:"四条不调 LLM 的路径：micro compact 的两条（时间触发清工具结果、cache_edits 删缓存）、API microcompact、session memory。reactive compact 本身要做摘要，是调 LLM 的；413 后先排空的 context collapse 属于另一套机制。compactConversation 摘要是最后兜底，与 OpenCode 和 Codex 每次压缩都调 LLM 形成对比。其余选项或违背分层设计（每次全量压缩），或把兜底当常态（始终调 LLM）。"},{question:"Cached microcompact 路径比直接修改本地消息更优的核心原因是什么？",options:["完全免去客户端侧计算降低本地资源占用开销","通过 cache_edits 让服务端删内容而客户端消息不变","实现代码量远小于传统修改消息的压缩方案","利用服务端精确估算以实现更准确的 token 计数"],correct:1,explanation:"cache_edits 块附在 API 请求层，客户端消息数组原样不动、cache key 不被破坏，但服务端 token 计数不再包含被删内容——这是「不破坏缓存前提下压缩」的核心。已发送的 edits 进 pinnedEdits 固定位置重发。其余选项的错误：它仍需客户端跟踪与注册工具结果；代码量不小；token 估算仍是客户端粗估。"},{question:"Auto compact 的断路器（连续失败 3 次停止重试）依据什么数据设计的？",options:["线上数据监测显示超长会话连续失败可达数千次严重浪费","线下压力测试中反复暴露的死循环导致 API 烧费急剧增加","模型训练阶段统计出的上下文压缩最佳失败容限值","缺乏充分的线上数据支撑仅为工程经验的主观猜测"],correct:0,explanation:"源码注释记录 BQ 2026-03-10 的数据：1,279 个 session 出现 50+ 次连续失败、最多 3,272 次，全局每天浪费约 25 万次 API 调用。断路器让该 session 内不再尝试 auto compact。这不是线下压测发现、更非训练统计或主观经验。"},{question:"Session memory compact 实现「零 LLM 调用压缩」的根本手段是什么？",options:["只压缩纯工具调用结果完全不做语义级别的摘要处理","基于纯规则匹配替代模型推理以实现零推理成本压缩","直接丢弃旧消息不做任何摘要处理以追求极致速度","将 LLM 调用成本前置到对话进行中的后台异步提取环节"],correct:3,explanation:"后台 forked agent 在对话进行中定期提取关键信息写文件（对话 10K tokens 起步、每 5K tokens 或 3 次工具调用更新），压缩触发时只剩读文件。LLM 成本没有消失，只是被挪出了压缩的关键路径。session memory 本身仍是 LLM 生成的摘要，不是规则匹配，也不是丢弃。"},{question:"query 循环里 413（prompt too long）错误为什么要先「扣留」（withhold）而不立即展示给用户？",options:["等待遥测系统完整记录错误上下文后再决定上报策略","避免用户在错误提示期间继续输入打断重试的完整性","给恢复逻辑留出机会成功后错误就无需再让用户看到","权限系统需要先确认错误内容是否包含敏感的信息"],correct:2,explanation:"扣留机制先把可恢复错误扣在手里：413 依次尝试排空 context collapse、reactive compact 压缩后重试，成功则错误消息永不 yield 出去，失败才浮出。用户体验是「处理得久一点」而非「出错后偷偷修」。扣留与遥测记录、防打断、权限检查均无关系。"}];return(E,s)=>{const a=t("Quiz");return n(),e("div",null,[s[0]||(s[0]=p("",125)),h(a,{questions:i})])}}});export{y as __pageData,F as default};
